import React, { HTMLAttributes, useState, useEffect, forwardRef } from 'react';
import classNames from 'classnames';
import styles from './tab-folder.module.scss';

export type TabFolderProps = {
  selectedTab?: HTMLElement;
  enableAnimation?: boolean;
} & HTMLAttributes<HTMLDivElement>;

type BorderStyle = {
  width: undefined | string;
  transform: undefined | string;
  transition: undefined | string;
};

export const TabFolder = forwardRef<HTMLDivElement, TabFolderProps>(
  ({ selectedTab, enableAnimation = false, className, ...rest }: TabFolderProps, ref) => {
    const [borderStyles, setBorderStyle] = useState<BorderStyle>({
      width: undefined,
      transform: undefined,
      transition: undefined,
    });

    useEffect(() => {
      if (selectedTab) {
        const styleObj: BorderStyle = { width: undefined, transform: undefined, transition: undefined };
        const offset = selectedTab.offsetLeft;

        styleObj.width = `${selectedTab.offsetWidth}px`;
        styleObj.transform = `translateX(${offset}px)`;
        if (enableAnimation) styleObj.transition = 'transform 150ms ease-in-out, width 150ms ease-in-out';

        setBorderStyle(styleObj);
      }
    }, [selectedTab, enableAnimation]);

    return (
      <div
        className={classNames(styles.tabFolder, styles.folderStyle, className)}
        style={borderStyles}
        ref={ref}
        {...rest}
      />
    );
  }
);
